 void load()throws Exception{catalog=new JSONObject(read(getAssets().open("catalog.json")));File update=new File(getFilesDir(),"catalog-update.json");if(update.exists()){try{JSONObject latest=new JSONObject(new String(java.nio.file.Files.readAllBytes(update.toPath()),StandardCharsets.UTF_8));validateCatalog(latest);latest=CatalogPriceUpdate.merge(catalog,latest);validateCatalog(latest);catalog=latest;}catch(Exception e){startupWarning="Обновлённый прайс не открывается; загружен встроенный каталог: "+e.getMessage();}}File f=new File(getFilesDir(),"data.enc");if(!f.exists()){db=new JSONObject().put("schemaVersion",DataMigration.CURRENT).put("users",new JSONArray()).put("projects",new JSONArray());return;}byte[] all=java.nio.file.Files.readAllBytes(f.toPath());if(all.length<29)throw new IOException("Файл базы повреждён");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Arrays.copyOfRange(all,0,12)));JSONObject original=new JSONObject(new String(c.doFinal(Arrays.copyOfRange(all,12,all.length)),StandardCharsets.UTF_8));db=original;int oldVersion=original.optInt("schemaVersion",1);JSONObject updated=DataMigration.migrate(original);MigrationReport report=migratePhotos(updated,true);if(report.failed>0)startupWarning="Не удалось перенести "+report.failed+" фото. Объекты доступны; исходные данные фото сохранены. Первое проблемное фото: "+report.firstFailure+". Сделайте резервную копию в настройках.";if(report.migrated>0||oldVersion<DataMigration.CURRENT){File migrationBackup=new File(getFilesDir(),"data-pre-migration.enc");java.nio.file.Files.copy(f.toPath(),migrationBackup.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);db=updated;try{F1SyncLedger.capture(db);saveRaw();migrationLog("Успех: схема "+oldVersion+" → "+DataMigration.CURRENT+", фото "+report.migrated);}catch(Exception e){db=original;java.nio.file.Files.copy(migrationBackup.toPath(),f.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);migrationLog("Откат схемы "+oldVersion+": "+e.getClass().getSimpleName());startupWarning="Миграция не сохранена, исходная база восстановлена: "+e.getMessage();}}loadSession();}
