 byte[] photoBytes(String data)throws Exception{String prefix="data:image/jpeg;base64,";if(!data.startsWith(prefix))throw new IOException("Некорректный формат фото");byte[] bytes=Base64.getDecoder().decode(data.substring(prefix.length()));if(bytes.length<4||(bytes[0]&255)!=255||(bytes[1]&255)!=216||(bytes[bytes.length-2]&255)!=255||(bytes[bytes.length-1]&255)!=217)throw new IOException("Повреждённый JPEG");return bytes;}
 static class MigrationReport{int migrated,failed;String firstFailure="";}
