 JSONArray photoPayload(JSONObject p,String arr)throws Exception{JSONArray source=p.optJSONArray(arr),out=new JSONArray();if(source==null)return out;for(int i=0;i<source.length();i++){try{JSONObject row=new JSONObject(source.getJSONObject(i).toString());if(!row.has("data"))row.put("data","data:image/jpeg;base64,"+Base64.getEncoder().encodeToString(photos().get(row.getString("id"))));photoBytes(row.getString("data"));out.put(row);}catch(Exception ignored){/* Keep the record in db; skip only its unavailable image in the view/export. */}}return out;}
 JSONObject backupContent()throws Exception{JSONObject out=new JSONObject().put("format","Arhilab-1").put("team",state().getJSONArray("users"));JSONArray projects=new JSONArray();JSONArray source=db.getJSONArray("projects");skippedBackupPhotos=0;for(int i=0;i<source.length();i++){JSONObject p=new JSONObject(source.getJSONObject(i).toString());for(String arr:new String[]{"photos","estimatePhotos"})if(p.has(arr)){JSONArray original=p.getJSONArray(arr),available=photoPayload(p,arr);skippedBackupPhotos+=original.length()-available.length();p.put(arr,available);}projects.put(p);}return out.put("projects",projects).put("catalog",catalog);}
 JSONObject fullBackupContent()throws Exception{JSONObject out=backupContent();if(skippedBackupPhotos>0)throw new IOException("Недоступно фото: "+skippedBackupPhotos+". Полная копия не создана.");JSONArray users=new JSONArray();for(int i=0;i<db.getJSONArray("users").length();i++){JSONObject u=new JSONObject(db.getJSONArray("users").getJSONObject(i).toString());u.remove("sessionHash");users.put(u);}out.put("format","Arhilab-2").put("schemaVersion",DataMigration.CURRENT).put("users",users);JSONObject settings=db.optJSONObject("settings");if(settings!=null)out.put("settings",new JSONObject(settings.toString()));return out;}
