 void stripCosts(JSONObject p)throws Exception{for(String k:new String[]{"deliveryCost","overhead","otherCost","purchases","expenses"})p.remove(k);for(String arr:new String[]{"lines","materials"}){JSONArray a=p.optJSONArray(arr);if(a!=null)for(int i=0;i<a.length();i++){a.getJSONObject(i).remove("cost");a.getJSONObject(i).remove("materialCost");}}JSONArray visible=new JSONArray();JSONArray payments=p.optJSONArray("payments");if(payments!=null)for(int i=0;i<payments.length();i++)if(payments.getJSONObject(i).optString("kind").equals("income"))visible.put(payments.getJSONObject(i));p.put("payments",visible);JSONArray estimates=p.optJSONArray("estimates");if(estimates!=null)for(int i=0;i<estimates.length();i++)stripCosts(estimates.getJSONObject(i));}
