 void validateCatalog(JSONObject c)throws Exception{if(!"ArhilabCatalog-2".equals(c.optString("format")))throw new Exception("Формат прайса не поддерживается");JSONArray works=c.getJSONArray("works"),materials=c.getJSONArray("materials");if(works.length()<1||materials.length()<1||works.length()>10000||materials.length()>10000)throw new Exception("Каталог пуст или слишком велик");Set<String> ids=new HashSet<>(),keys=new HashSet<>();for(int i=0;i<materials.length();i++){JSONObject m=materials.getJSONObject(i);String id=m.getString("id"),name=m.getString("name");if(id.isEmpty()||name.isEmpty()||!ids.add(id))throw new Exception("Повтор или пустой SKU");double cost=m.getDouble("cost");if(!Double.isFinite(cost)||cost<0||cost>1e12)throw new Exception("Некорректная закупка SKU");}for(int i=0;i<works.length();i++){JSONObject w=works.getJSONObject(i);if(!keys.add(w.getString("key"))||w.getString("id").isEmpty())throw new Exception("Повтор работы");for(String tier:new String[]{"economy","standard","premium"}){JSONObject kit=w.getJSONObject("tiers").getJSONObject(tier);double cost=kit.getDouble("materialCost");if(!Double.isFinite(cost)||cost<0||cost>1e12)throw new Exception("Некорректная цена комплекта");JSONArray refs=kit.getJSONArray("materialIds");for(int j=0;j<refs.length();j++)if(!ids.contains(refs.getString(j)))throw new Exception("Материал комплекта не найден: "+refs.getString(j));if(refs.length()==0&&cost!=0)throw new Exception("Комплект без товаров содержит стоимость");}}}
 JSONObject matchingWork(JSONObject l)throws Exception{JSONArray works=catalog.getJSONArray("works");for(int i=0;i<works.length();i++){JSONObject w=works.getJSONObject(i);if(!l.optString("key").isEmpty()&&l.optString("key").equals(w.optString("key")))return w;if(l.optString("name").equals(w.optString("name"))&&l.optString("category").equals(w.optString("category")))return w;}throw new Exception("Работа отсутствует в каталоге");}
 void setTier(JSONObject l,JSONObject w,String tier,int markup)throws Exception{if(!Arrays.asList("economy","standard","premium").contains(tier))throw new Exception("Неверный класс материалов");JSONObject kit=w.getJSONObject("tiers").getJSONObject(tier);JSONArray ids=kit.getJSONArray("materialIds"),names=new JSONArray();for(int i=0;i<ids.length();i++)names.put(find(catalog.getJSONArray("materials"),ids.getString(i)).getString("name"));l.put("materialTier",tier).put("materials",names).put("materialNote",kit.optString("note")).put("materialCost",kit.getDouble("materialCost")).put("materialPrice",MaterialMarkup.price(kit.getDouble("materialCost"),markup)).put("autoMaterial",ids.length()>0);l.remove("tiers");l.remove("kitOverrides");}
 void refreshKitOverrides(JSONObject l,JSONObject w,int markup)throws Exception{JSONObject kit=w.getJSONObject("tiers").getJSONObject(l.optString("materialTier","standard")),overrides=l.optJSONObject("kitOverrides");JSONArray ids=kit.getJSONArray("materialIds"),names=new JSONArray();double cost=kit.getDouble("materialCost");for(int i=0;i<ids.length();i++){String base=ids.getString(i);JSONObject original=find(catalog.getJSONArray("materials"),base),override=overrides==null?null:overrides.optJSONObject(base);if(override==null){names.put(original.getString("name"));continue;}JSONObject replacement=find(catalog.getJSONArray("materials"),override.getString("sku"));double qty=override.getDouble("qty");cost+=(replacement.getDouble("cost")-original.getDouble("cost"))*qty;names.put(replacement.getString("name"));}if(cost<0)throw new Exception("Замена делает стоимость комплекта отрицательной");l.put("materials",names).put("materialCost",Math.round(cost*100)/100.0).put("materialPrice",MaterialMarkup.price(cost,markup));}
